// ?getBridgeHeight@Bridge@@QAEMPBUCoord3D@@PAU2@@Z
// partial score=0.4714 date=2026-09-28
// cl: /DNDEBUG /MD /EHs-c-
// Bridge::getBridgeHeight, retail 0x001A7520 size 664.
//
// ZH source: reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Source/GameLogic/Map/TerrainLogic.cpp
// (Bridge::getBridgeHeight) -- the m_extra==0 "else" branch below is that ZH body near-verbatim.
// BFME added the m_extra!=0 slope branch; the m_extra offset (+0x8c) is cross-validated against
// the landed sibling Code/GameEngine/Source/GameLogic/Map/BridgeIsPointOnBridge.cpp, whose
// BridgePointOnBridgeShim class collapses m_from/m_to/m_bridgeWidth into one infoPad[0x1C] but
// otherwise shares this exact member layout through m_extra.
//
// Coord3D::normalize / PlaneClass::Set / PlaneClass::Compute_Intersection are declared WITHOUT
// bodies (matching retail, which calls all three out of line through an ICF-folded j_ thunk --
// confirmed in the disassembly at +0x112/+0x11b and the plane-path calls at +0x225/+0x266). The
// real WWMath headers define these inline, which the compiler WOULD inline here and produce a
// different, larger instruction stream (tried: regressed 652B -> 633B); the declare-only shim
// keeps retail's real-call shape.
//
// Named float constants confirmed by reading the retail image directly (not literals -- retail
// loads all three through memory operands, not FPU immediates): BfmeShadowScale (VA 0x0109BF3C)
// = -1.0f, BfmeZeroRange (VA 0x01075350) = 0.0f, g_bfmeDefaultBU (VA 0x01075334) = 1.0f. All
// three are already declared/pinned elsewhere in Code/ (grep BfmeShadowScale/BfmeZeroRange/
// g_bfmeDefaultBU); reusing the same extern spelling here so the compiled body references the
// same relocations retail does instead of materialising -1.0f/0.0f/1.0f as inline immediates.
//
// The slope branch reuses ONE packed scratch struct (Align34, matching retail's stack-slot
// reuse: nFrom/gap/nTo/scratch/tmp share the SAME memory the plane-path below also reuses)
// rather than separate named locals -- separate locals compiled 44B over target; the packed
// struct is what gets retail's tighter stack frame (sub esp,0x34).
//
// SESSION 2026-09-28 (space-bunny-free, second pass). Frame map of the plane branch decoded
// from retail directly (build/esp.py + build/fm.py, `sub esp,0x34` / `push esi` modelled):
// with F = the post-`sub esp,0x34` frame base, retail's plane path uses
//   F+0x14 left1 (fromLeft), F+0x20 right1 (fromRight), F+0x2c left2 (toLeft),
//   F+0x00 the PlaneClass `this` (lea ecx,[esp+0x10] after 3 pushes),
//   and F+0x30 = &t, which is the DEAD pLoc argument slot (retail +0x23b `lea eax,[esp+0x3c]`
//   and +0x287 `fld [esp+0x3c]`, both = E+0 = pLoc). The packed Align34 spelling already lands
//   left1/right1/left2 on exactly F+0x14/F+0x20/F+0x2c; only the plane `this` sits 0x10 instead
//   of F+0x00, and no source spelling moves it (see the rejected list below).
//
//   TWO NEW LEVERS FOUND AND MEASURED THIS SESSION (probe 356 -> 327 non-reloc diffs,
//   structural differences 31 -> 26, normalised instruction match 0.768 -> 0.800,
//   misaligned relocation sites 11 -> 8, total still 652B vs retail's 664B):
//
//   (1) `-0.0f` is NOT the spelling retail used. MSVC 7.1's constant folder folds the unary
//       minus of a zero literal away: `-0.0f` and even the double `-0.0` both become +0.0f
//       and store 0x00000000, but retail stores 0x80000000 at +0xaf and +0xf2. Verified in
//       isolation (build/nz2.cpp, 12 spellings in one TU): only `0.0f * -1.0f` and
//       `-1.0f * 0.0f` keep the sign of zero -- the multiply is folded as a real
//       multiplication, not as a negation. Both -0.0f sites now match retail byte for byte.
//       Do NOT "clean this up" back to -0.0f: it re-breaks two instructions.
//
//   (2) The -1.0f scale sites need `fld [lhs]; fmul [BfmeShadowScale]`, which is the
//       opposite operand side from the `fld [global]; fmul [lhs]` that plain `x * kc`
//       produces (verified in isolation: build/q.cpp, build/s.cpp, build/t.cpp -- 20
//       spellings, and *swapping the written operand order changes nothing*, because MSVC
//       7.1 canonicalises a commutative float multiply). The one spelling that flips the
//       choice is reading the lhs through a `volatile float *`: the volatile load cannot be
//       sunk below the multiply, so the value is pushed first and the global becomes the
//       fmul memory operand. Applied to the three sites whose lhs retail pushes
//       (f.nFrom.x at +0xab, f.scratch.Y at +0xee, f.nTo.y at +0x104). Semantics are
//       unchanged -- volatile only constrains the optimiser, and the slots are
//       single-threaded locals whose address never escapes.
//
//   RULED OUT THIS SESSION, each measured on top of the two levers above:
//   (3) The x87 operand ORDER of the two comparison dot products. Retail evaluates the
//       x-term first (+0x90 `fld [esp+8]; fmul st(2)`) and pushes the register operand for
//       the y-term (+0x96 `fld st(1); fmul [esp+0x30]`); this build evaluates the y-term
//       first and uses `fmul st(n)` for both. Six in-body spellings (term order swapped
//       both ways, register operand written on the left in either term, named temporaries)
//       compile BYTE-IDENTICALLY, and an isolated 8-function TU (build/dot.cpp,
//       build/memreg.cpp) shows the same normalisation: MSVC 7.1 always picks the same
//       product order and operand side for `a*b + c*d` regardless of how it is written.
//       This is compiler-internal register allocation, not a source-shape defect.
//   (4) The natural `Vector3 left1(...); PlaneClass plane;` locals of the ZH source.
//       Retail's 0x34 frame does equal plane(16) + three Vector3(12), but writing them as
//       real locals blows the frame to 0x84 (730B) because the slope branch's packed
//       scratch and the plane locals then coexist; with `Vector3` given a user-declared
//       3-arg constructor the same shape regresses to 677B, and spelling the three
//       vectors as `Coord3D` locals copied from m_* gives 652B/343 diffs, worse than the
//       reinterpret_cast spelling. The packed scratch is load-bearing; keep it.
//   (5) Making the two dot-product comparison terms volatile (to force the memory side
//       retail uses) drops to 648B and 413 diffs. Clearly worse.
//   (6) Routing the pLoc-x difference through a named frame slot (to reproduce retail's
//       `fstp [esp+0x30]` spill at +0x130) reaches 656B but 330 diffs.
//
//   REMAINING BLOCKER (unchanged family, now with the -0.0f half of it closed): the first
//   structural divergence is still the x87 product order at +0x90 (item 3), and that is
//   compiler-internal. Size is still 652B against retail's clean 664B extent (ret 8 at
//   +0x295, INT3 at +0x298), split 427/203 against retail's 447/197, so the gap is
//   still two-sided and no size-only fix to one branch can close it.

extern const float BfmeShadowScale;
extern const float BfmeZeroRange;
extern const float g_bfmeDefaultBU;

struct Coord3D
{
	float x;
	float y;
	float z;
	void normalize();
};

class Vector3
{
public:
	float X;
	float Y;
	float Z;
};

class PlaneClass
{
public:
	Vector3 N;
	float D;

	void Set(const Vector3 &point1, const Vector3 &point2, const Vector3 &point3);
	bool Compute_Intersection(const Vector3 &p0, const Vector3 &p1, float *set_t) const;
};

class Bridge
{
public:
	float getBridgeHeight(const Coord3D *pLoc, Coord3D *normal);

private:
	void *m_vptr;
	void *m_next;
	void *m_templateName;
	Coord3D m_from;
	Coord3D m_to;
	float m_bridgeWidth;
	Coord3D m_fromLeft;
	Coord3D m_fromRight;
	Coord3D m_toLeft;
	Coord3D m_toRight;
	char m_infoTail[0x78 - 0x58];
	char m_bounds[0x10];
	int m_layer;
	void *m_extra;
};

struct Align34
{
	Coord3D nFrom;
	float gap;
	Coord3D nTo;
	Vector3 scratch;
	float tmp;
	float pad[2];
};

float Bridge::getBridgeHeight(const Coord3D *pLoc, Coord3D *normal)
{
	Align34 f;
	if (m_extra)
	{
		Coord3D *toPtr = &m_to;
		f.scratch = *reinterpret_cast<Vector3 *>(toPtr);
		float alongX = f.scratch.X - m_from.x;
		float alongY = f.scratch.Y - m_from.y;
		f.nFrom.x = m_fromRight.y;
		f.nFrom.z = 0.0f;
		f.tmp = m_fromRight.x - m_fromLeft.x;
		f.nTo.z = 0.0f;
		f.nFrom.y = f.tmp;
		f.nFrom.x = f.nFrom.x - m_fromLeft.y;
		f.nTo.y = m_toRight.y;
		f.scratch.X = m_toRight.x - m_toLeft.x;
		f.scratch.Y = f.nTo.y - m_toLeft.y;
		f.nTo.x = f.scratch.Y;
		f.nFrom.x = -f.nFrom.x;
		f.nTo.y = -f.scratch.X;
		if (f.nFrom.x * alongX + f.nFrom.y * alongY < BfmeZeroRange)
		{
			// -0.0f spelled as the product MSVC 7.1 does not fold to +0.0f.
			f.nFrom.z = 0.0f * -1.0f;
			// volatile lhs read: forces `fld [lhs]; fmul [scale]`, retail's operand side.
			f.nFrom.x = *reinterpret_cast<volatile float *>(&f.nFrom.x) * BfmeShadowScale;
			f.nFrom.y = f.tmp * BfmeShadowScale;
		}
		if (f.nTo.x * alongX + f.nTo.y * alongY > BfmeZeroRange)
		{
			f.nTo.z = 0.0f * -1.0f;
			f.nTo.x = *reinterpret_cast<volatile float *>(&f.scratch.Y) * BfmeShadowScale;
			f.nTo.y = *reinterpret_cast<volatile float *>(&f.nTo.y) * BfmeShadowScale;
		}
		f.nFrom.normalize();
		f.nTo.normalize();
		f.tmp = f.nFrom.x * (pLoc->x - m_from.x) + f.nFrom.y * (pLoc->y - m_from.y);
		f.gap = f.nTo.x * (pLoc->x - toPtr->x) + f.nTo.y * (pLoc->y - toPtr->y);
		f.scratch.X = g_bfmeDefaultBU / (f.tmp + f.gap);
		f.scratch.Y = f.scratch.X * f.tmp;
		f.scratch.Z = f.scratch.X * f.gap;
		f.tmp = (m_to.z + (m_from.z - m_to.z) * f.scratch.Z) * (g_bfmeDefaultBU - f.scratch.Z)
			+ (m_from.z + (m_to.z - m_from.z) * f.scratch.Y) * (g_bfmeDefaultBU - f.scratch.Y);
		if (normal)
		{
			normal->x = 0.0f;
			normal->y = 0.0f;
			normal->z = 1.0f;
		}
		return f.tmp;
	}

	{
		char *base = reinterpret_cast<char *>(&f);
		Vector3 &left1 = *reinterpret_cast<Vector3 *>(base + 0x10);
		Vector3 &right1 = *reinterpret_cast<Vector3 *>(base + 0x1c);
		Vector3 &left2 = *reinterpret_cast<Vector3 *>(base + 0x28);
		PlaneClass &plane = *reinterpret_cast<PlaneClass *>(base + 0x0c);
		left1 = *reinterpret_cast<Vector3 *>(&m_fromLeft);
		right1 = *reinterpret_cast<Vector3 *>(&m_fromRight);
		left2 = *reinterpret_cast<Vector3 *>(&m_toLeft);
		plane.Set(left1, right1, left2);
		right1.X = pLoc->x;
		left2.X = pLoc->x;
		right1.Y = pLoc->y;
		left2.Y = pLoc->y;
		right1.Z = 0.0f;
		left2.Z = 1000.0f;
		plane.Compute_Intersection(right1, left2, &f.tmp);
		if (normal)
		{
			normal->x = plane.N.X;
			normal->y = plane.N.Y;
			normal->z = plane.N.Z;
		}
		return f.tmp * 1000.0f;
	}
}
